class UEInfo(object):
    def __init__(self, eqindex=None, imsi=None, imei=None):
        self.eqindex = eqindex
        self.imsi = imsi
        self.imei = imei


class UE(object):
    def __init__(self, api, adb, ue_info, service):
        self._info = ue_info
        self._api = api
        self._adb = adb
        self._service = service

    @property
    def imsi(self):
        return self._info.imsi

    @property
    def eqindex(self):
        return self._info.eqindex

    @property
    def serial_number(self):
        return self._adb.serial_number

    @property
    def adb(self):
        return self._adb

    @property
    def service(self):
        return self._service

    def release(self):
        self._service.release_ue(self)

    def startlog(self, logpath, logname, until_timeout=None):
        """
        execute StartLog command to collect available logs for L1/L2/L3 as separate files by UE on control pc
        Only L3 log available for Hisillicon.
        e.g.
        UE1 log target file: logname-1.xxx
        UE2 log target file: logname-2.xxx

        :param str logpath: log folder on control pc to save logs
        :param str logname: log name prefix
        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "StartLog",
            "Param": {
                  "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        return self._api.StartLog(logpath, logname, until_timeout=until_timeout)

    def stoplog(self, until_timeout=None):
        """
        execute Stoplog command to stop collecting logs

        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "Stoplog",
            "Param": {
                  "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        return self._api.StopLog(until_timeout=until_timeout)

    def startultraffic(self, protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                       until_timeout=None):
        """
        execute StartULtraffic to start Up Link Traffic

        :param str protocol: traffic protocol, e.g. 'UDP', others???
        :param str address: target(e.g. app server) ip address
        :param int port: target port NO.
        :param int testtime: time last for traffic in second???
        :param int bandwidth: bandwidth in Kbps
        :param int buffersize: buffersize in KB
        :param int packetsize: packetsize in Byte
        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "StartULtraffic",
            "EQIndex": 1, # {-1, 1~n}, -1 means all UEs, 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        return self._api.StartULtraffic(self._info.eqindex,
                                        protocol,
                                        address,
                                        str(port),
                                        str(testtime),
                                        bandwidth,
                                        buffersize,
                                        packetsize,
                                        until_timeout=until_timeout)

    def stopultraffic(self, until_timeout=None):
        """
        execute StopULtraffic to stop Down Link Traffic

        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "StopULtraffic",
            "EQIndex": 1, # {-1, 1~n}, -1 means all UEs, 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        return self._api.StopULtraffic(self._info.eqindex, until_timeout=until_timeout)

    def attach(self, uemode, until_timeout=None):
        """
        execute Attach command to attach UE

        :param str uemode: "4G" or "5G_SA" or "5G_NSA"
        :param Optional[int] until_timeout: execution timeout in second, 60s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "Attach",
            "EQIndex": -1, # UNION[int, list] {-1,1~n} or [1, 2,3...],
                           # -1 means all UEs, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
                 "SubStates": [0, 0, 0...]   # if EQIndex is -1, return all UE’s result.
                                             # return 0 if success, otherwise return the error codes.
            }
        }
        """
        return self._api.Attach(self._info.eqindex, uemode, until_timeout=until_timeout)

    def detach(self, withpdu, until_timeout=None):
        """
        execute Detach command to detach UE

        :param Optional[int] until_timeout: execution timeout in second, 30s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "Detach",
            "EQIndex": -1, # UNION[int, list] {-1,1~n} or [1, 2,3...],
                           # -1 means all UEs, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
                 "SubStates": [0, 0, 0...]   # if EQIndex is -1, return all UE’s result.
                                             # return 0 if success, otherwise return the error codes.
            }
        }
        """
        return self._api.Detach(self._info.eqindex, withpdu, until_timeout=until_timeout)

