    def startmos(self, callmode, calledue, callednum, videocall, duration, testcount, algorithms,
                 polqaversion, mosboxtype, groupno, until_timeout=None):
        """
        Start Mos Test

        :param int callmode: Call Mode, 0:"MO MT",1:"MOC",2:"MTC".
        :param int calledue: Called UE, {1~n} 1 means the first UE, 2 means the second UE, and so forth.
        :param str callednum: Called phone number.
        :param int videocall: Video Call, 0:meas No,1:meas.
        :param int duration: Call Duration, The unit is seconds ,0 meas long.
        :param int testcount: Test Count, Test Count,0 meas infinite test.
        :param int algorithms: 0:"PESQ NB",1:"POLQA NB",2:"POLQA SWB",3:"PESQ WB".
        :param int polqaversion: 0:"V1.1", 1:"V2.4".
        :param int mosboxtype: 0:"Multi MOS Box",1:"Single MOS Box".
        :param int groupno: 0-7, if CallMode is 0: 0 means Group No.0, 1 means Group No.1, and so forth.
                            if CallMode is other: 0 means Channel No.0, 1means Channel No.1, and so forth.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return self._api.StartMOS(
            self._info.eqindex, callmode, calledue, callednum, videocall, duration, testcount, algorithms,
            polqaversion, mosboxtype, groupno, until_timeout=until_timeout)

    def stopmos(self, until_timeout=None):
        """
        Stop Mos Test

        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return self._api.StopMOS(self._info.eqindex, until_timeout=until_timeout)

    def startftpdl(self, host, port, username, password,
                   modetype, savefile, hostdir, localdir, duration,
                   threadcount, ftptype, until_timeout=None):
        """
        Stat FTP DL test

        :param str host: host pc ip.
        :param int port: host pc port.
        :param str username: username.
        :param str password: password.
        :param int modetype: mode type.
        :param bool savefile: whether to save the data file when downloading.
        :param str hostdir: host dir path.
        :param str localdir: local dir path.
        :param int duration: duration.
        :param int threadcount: thread count.
        :param str ftptype: protocol type FTP: ftp server , SFTP : sftp server.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :return: dict
        e.g.
        {
          "CMD": "StartFTPDL
          "EQIndex": 1, //{1, 1~n}, 1 means all UEs, 1 means the first UE,
                        //2 means the second UE, and so forth.
          "Param": {
                     "Host ": 183.221.242.254,
                     "Port ": 21,
                     "Username": "xxx",
                     "Password": "xxx",
                     "ModeType": 1,
                     "SaveFile": true,  //Whether to save the data file when downloading.
                     "HostDir": "./test.dat",
                     "LocalDir": "F:",
                     "Duration": 303000,  //download duration (s).
                     "ThreadCount": 3300,  //Number of download threads.
                     "FtpType": "FTP"  //Protocol type FTP: ftp server , SFTP : sftp server.
          }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return self._api.StartFTPDL(self._info.eqindex, host=host, port=port, username=username, password=password,
                                    modetype=modetype, savefile=savefile, hostdir=hostdir, localdir=localdir,
                                    duration=duration, threadcount=threadcount, ftptype=ftptype,
                                    until_timeout=until_timeout)

    def startftpul(self, host, port, username, password,
                   modetype, hostdir, size, duration, threadcount,
                   ftptype, deletefile, until_timeout=None):
        """
        Stat FTP UL test

        :param str host: host pc ip.
        :param int port: host pc port.
        :param str username: username.
        :param str password: password.
        :param int modetype: mode type.
        :param str hostdir: host dir path.
        :param int size: size.
        :param int duration: duration.
        :param int threadcount: thread count.
        :param str ftptype: protocol type FTP: ftp server , SFTP : sftp server.
        :param bool deletefile: Whether to delete the remote file after the upload service ends.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :return: dict
        e.g.
        {
          "CMD": "StartFTPUL"
          EQIndex": 1, //{ 1, 1~n}, 1 means all UEs, 1 means the first UE,
                       //2 means the second UE, and so forth.
          "Param": {
                    "Host": "183.221.242.254",
                    "Port": 21,
                    "Username": "xxxxxx",
                    "Password": "xxxxxx",
                    "ModeType": 1,
                    "HostDir": "./", //Server file path.
                    "Size": 100000, //Upload file size (KB)..
                    "Duration": 300, //upload duration (s).
                    "ThreadCount": 30, //The number of upload threads.
                    "FtpType": "FTP",  //Protocol type FTP: ftp server , SFTP : sftp server.
                    "DeleteFile": true  //Whether to delete the remote file after the upload service ends.
          }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return self._api.StartFTPUL(self._info.eqindex, host=host, port=port, username=username, password=password,
                                    modetype=modetype, hostdir=hostdir, size=size, duration=duration,
                                    threadcount=threadcount, ftptype=ftptype, deletefile=deletefile,
                                    until_timeout=until_timeout)

    def startping(self, host, packetsize, livetime, timeout, atping, until_timeout=None):
        """
        Stat Ping test

        :param str host: host pc ip address.
        :param int packetsize: host pc port.
        :param int livetime: life time.
        :param int timeout: Timeout time (ms).
        :param bool atping: Whether to use AT command to test Ping (only for IoT module devices), true or false.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :return: dict
        e.g.
        {
          "CMD": "StartPing",
          "EQIndex": 1, //{1, 1~n}, 1 means all UEs, 1 means the first UE,
                        //2 means the second UE, and so forth.
          "Param": {
                     "Host": "8.8.8.8", //IP address.
                     "PacketSize": 50, //Ping packet size (Bytes)
                     "LiveTime": 50, //lifetime.
                     "TimeOut": 1500, //Timeout time (ms)
                     "ATPing": false, //Whether to use AT command to test Ping (only for IoT module devices), true or false
          }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return self._api.StartPing(self._info.eqindex, host=host, packetsize=packetsize, livetime=livetime,
                                   timeout=timeout, atping=atping, until_timeout=until_timeout)

    def starthttppage(self, testmode, clearcache, timeout, websiteduration, dorandomwebsitecount,
                      requiredwebsitelist, randomwebsitelist, until_timeout=None):
        """
        Stat HTTP page test

        :param int testmode: test mode.
        :param bool clearcache: Whether to clear the cache when refreshing the test.
        :param int timeout: Timeout time (ms).
        :param int websiteduration: The interval between browsing between different URLs.
        :param int dorandomwebsitecount: The number of random addresses per execution.
        :param list requiredwebsitelist: List of required website addresses.
        :param list randomwebsitelist: A list of random website addresses.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, UE]] ue: ue under pioneer service control
        :return: dict
        e.g.
        {
          "CMD": "StartHTTPPage",
          "EQIndex": 1, //{1, 1~n}, 1 means all UEs, 1 means the first UE,
                        //2 means the second UE, and so forth.
          "Param": {
                    "TestMode": 0, //Test mode 0:Logon Page,1:Refresh Page.
                    "ClearCache": true,  //Whether to clear the cache when refreshing the test
                    "TimeOut": 90,  //Timeout time (s).
                    "WebSiteDuration": 5,  //The interval between browsing between different URLs.
                    "DoRandomWebSiteCount": 4,  //The number of random addresses per execution.
                    "RequiredWebSiteList":  //List of required website addresses.
                        [{
                           "WebSiteName": "Test website name",
                           "WebSite": "www.baidu.com", //Test website URL.
                           "IsChecked": true,  //Whether the site is tested.
                         },
                         {
                           "WebSiteName": "Test website name",
                           "WebSite": "www.jd.com", //Test website URL.
                           "IsChecked": true,  //Whether the site is tested.
                         },
                         …
                        ]

                    "RandomWebSiteList":  //A list of random website addresses
                        [{
                          "WebSiteName": "12306",  //Test website name.
                          "WebSite": "www.12306.cn",  //Test website URL.
                          "IsChecked": true",  //Whether the site is tested.
                         },
                         {
                          "WebSiteName": "Tencent",  //Test website name.
                          "WebSite": "www.qq.com",  //Test website URL.
                          "IsChecked": true,  //Whether the site is tested.
                         },
                         …
                        ]
          }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return self._api.StartHTTPPage(self._info.eqindex, testmode=testmode, clearcache=clearcache, timeout=timeout,
                                       websiteduration=websiteduration, dorandomwebsitecount=dorandomwebsitecount,
                                       requiredwebsitelist=requiredwebsitelist, randomwebsitelist=randomwebsitelist,
                                       until_timeout=until_timeout)

    def stoptest(self, until_timeout=None):
        """
        execute StopTest command to stop test plan which is executing now

        :param Optional[int] until_timeout: execution timeout in second, 10s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "StopTest",
            "Param": {
                  "State": 0  # return 0 if success, otherwise return the error codes
                  "SubStates":[0,0,0…] //if EQIndex is -1, return all UE result
            }
        }
        """
        return self._api.StopTest(self._info.eqindex, until_timeout=until_timeout)

    def startcall(self, number, connecttime, duration, longcall, until_timeout=None):
        """
        start call

        :param str number: called number.
        :param int connecttime: connection time limit(s).
        :param int duration: call duration(s).
        :param bool longcall: whether long call, true or false.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": " StartCall ",
            "EQIndex": 1, //{1, 1~n}, 1 means all UEs, 1 means the first UE,
                          //2 means the second UE, and so forth.
            "Param": {
                  "State": 0  # return 0 if success, otherwise return the error codes
                  "SubStates":[0,0,0…] //if EQIndex is -1, return all UE result
            }
        }
        """
        return self._api.StartCall(self._info.eqindex, number, connecttime, duration, longcall, until_timeout=until_timeout)

    def physicalpoweron(self, waitforoper, until_timeout=None):
        """
        execute PhysicalPowerOn command to physical power on.

        :param bool waitforoper: ”true” or ”false”,”true” means wait for module update status.
        :param Optional[int] until_timeout: execution timeout in second, 60s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": " PhysicalPowerOn ",
            "EQIndex": [1,2,..] , //{1~n}, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                "State": 0,     //return 0 if success, return -1 if failure or abnormal.
                "IsOnLine": 1  //return 1 if true, return 0 if false.
            }
        }
        """
        return self._api.PhysicalPowerOn(self._info.eqindex, waitforoper, until_timeout=until_timeout)

    def physicalpoweroff(self, waitforoper, until_timeout=None):
        """
        execute PhysicalPowerOff command to physical power off.

        :param bool waitforoper: ”true” or ”false”,”true” means wait for module update status.
        :param Optional[int] until_timeout: execution timeout in second, 60s by default

        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": " PhysicalPowerOff ",
            "EQIndex": [1,2,..] , //{1~n}, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                "State": 0,     //return 0 if success, return -1 if failure or abnormal.
                "IsOffLine": 1  //return 1 if true, return 0 if false.
            }
        }
        """
        return self._api.PhysicalPowerOff(self._info.eqindex, waitforoper, until_timeout=until_timeout)
